#include <iostream>

class Fraction {
public:
    int numerator;
    int denominator;

    void reduce() {
        int a = numerator;
        int b = denominator;
        while (b != 0) {
            int t = a % b;
            a = b;
            b = t;
        }
        int g = a;
        if (g != 0) {
            numerator /= g;
            denominator /= g;
        }
    }

    void print() {
        std::cout << numerator << "/" << denominator << "\n";
    }
};

int main() {
    int n;
    std::cin >> n;
    for (int i = 0; i < n; ++i) {
        int num, den;
        std::cin >> num >> den;
        Fraction f;
        f.numerator = num;
        f.denominator = den;
        f.reduce();
        f.print();
    }
    return 0;
}
